import{_ as r,o,c as s,a2 as a}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"お気に入り","description":"","frontmatter":{},"headers":[],"relativePath":"ja-JP/user-guide/settings/favorites.md","filePath":"ja-JP/user-guide/settings/favorites.md","lastUpdated":1788164125000}'),e={name:"ja-JP/user-guide/settings/favorites.md"};function n(i,t,l,g,d,c){return o(),s("div",null,[...t[0]||(t[0]=[a('<h1 id="お気に入り" tabindex="-1">お気に入り <a class="header-anchor" href="#お気に入り" aria-label="Permalink to &quot;お気に入り&quot;">​</a></h1><p>お気に入り機能は、頻繁に使用するフォルダー、ファイル、スクリプト、Web サイトの URL を固定登録し、独自のカスタム名と最優先の検索順位を付与する機能です。設定は <strong>設定 → お気に入り</strong> で行います。</p><h2 id="_1-お気に入りの追加" tabindex="-1">1. お気に入りの追加 <a class="header-anchor" href="#_1-お気に入りの追加" aria-label="Permalink to &quot;1. お気に入りの追加&quot;">​</a></h2><p>画面上部の登録フォーム：</p><ul><li><strong>表示名</strong>：任意のカスタムエイリアス（空欄の場合、対象がローカルパスであれば自動的にファイル名やフォルダー名が設定されます）。</li><li><strong>対象パス</strong>：ローカルの絶対パス、または <code>http://</code> / <code>https://</code> で始まる Web サイトの URL を入力。</li><li><strong>参照ボタン</strong>：<strong>フォルダーを参照</strong> または <strong>ファイルを参照</strong> をクリックして標準ダイアログから選択可能。</li><li><strong>追加ボタン</strong>：有効なパスを入力後、<strong>追加</strong> をクリックして登録。</li></ul><h2 id="_2-一覧管理とドラッグによる並び替え" tabindex="-1">2. 一覧管理とドラッグによる並び替え <a class="header-anchor" href="#_2-一覧管理とドラッグによる並び替え" aria-label="Permalink to &quot;2. 一覧管理とドラッグによる並び替え&quot;">​</a></h2><p>登録されたお気に入りは下部の一覧に表示され、柔軟に管理できます。</p><ul><li><strong>6 点ドラッグハンドルによる並び替え</strong>：各行の左側にある 6 点ハンドルをドラッグ＆ドロップして順序を変更できます。また、右側の <strong>上へ移動</strong> / <strong>下へ移動</strong> ボタンでも調整可能です。ここでの順序は検索結果やクイックナビゲーションでの表示順に直接反映されます。</li><li><strong>その場で編集</strong>：編集をクリックすると対象の行がそのまま編集欄に変わり、行内で保存またはキャンセルできます。上部の追加フォームは再利用しません。</li><li><strong>削除</strong>：お気に入りから安全に削除します。</li><li><strong>一覧をクリア</strong>：一覧に項目がある場合、一覧見出しの右側にあるボタンですべてのお気に入りを一括削除できます。一覧が空の場合、このボタンは非表示です。</li></ul><p>検索結果のアクションメニューから、存在するファイルまたはフォルダーを 1 件だけお気に入りに追加することもできます。Lertaro は表示名を入力するダイアログを開き、同じパスが登録済みの場合はこのアクションを表示しません。</p><h2 id="_3-検索での呼び出しと表示" tabindex="-1">3. 検索での呼び出しと表示 <a class="header-anchor" href="#_3-検索での呼び出しと表示" aria-label="Permalink to &quot;3. 検索での呼び出しと表示&quot;">​</a></h2><ul><li><strong>スターマーク（★）</strong>：検索結果にお気に入り項目が含まれる場合、パスの横に目立つ <strong>★</strong> マークが表示されます。</li><li><strong>カスタムエイリアス検索</strong>：深い階層にあるファイルに覚えやすい名前を付けることができます（例: <code>D:\\Workspace\\2026\\Q1\\Financial\\Summary.xlsx</code> に <code>第1四半期財務</code> と命名）。検索ボックスでその名前を入力するだけで瞬時に呼び出せます。</li><li><strong>複数機能との連携</strong>：登録したお気に入りは、<a href="./../hotkeys.html#3-クイックナビゲーションマウス操作"><strong>クイックナビゲーション</strong></a> メニューや <a href="./quick-panel.html#4-プラグイン動的タブplugin-tabs"><strong>クイックパネル</strong></a> の「お気に入り」タブに自動的に反映されます。</li></ul>',11)])])}const _=r(e,[["render",n]]);export{u as __pageData,_ as default};
